
    #[test]
    fn child_complete_group_source_candidate_ids_preserve_original_domains_and_retained_index(){
        mod ids{include!("./🧩️child-operations/🆔️ids/🦀️.rs");}
        use semio_framework_os_kernel::{os_pack::codec::ByteSpan,os_spr::io::binary::operation_bytes::OperationSourceCollection};
        use semio_framework_value::{NativeEncodeControl,ErasedSnapshotRetirement,SnapshotRetirementStep,list::PagedList,paged_text::{PagedText,InlineTextBuffer,TextReadSource}};
        struct Order<'a>{sources:&'a PagedList<OwnedOperationBytes,2>,order:&'a[usize],missing:bool}
        impl OperationSourceCollection for Order<'_>{fn len(&self)->usize{self.order.len()}fn source_at(&self,index:usize)->Option<ByteSpan<'_>>{if self.missing&&index==1{return None}self.sources.source_at(*self.order.get(index)?)}}
        struct Children<'a>{identifiers:[&'a str;4],operations:[Order<'a>;4],order:&'a[usize],missing:bool}
        impl ids::ChildFingerprintSources for Children<'_>{fn len(&self)->usize{self.order.len()}fn child_at(&self,index:usize)->Option<ids::ChildFingerprintSource<'_>>{if self.missing&&index==1{return None}let original=*self.order.get(index)?;Some(ids::ChildFingerprintSource{identifier:&self.identifiers[original],operations:&self.operations[original]})}}
        fn close_indices<const N:usize>(owner:&mut PagedList<usize,N>){for _ in 0..8194{if owner.pop().is_some(){continue}if owner.terminal_is_empty(){break}let step=owner.release_empty_page(4096).unwrap();assert!(step.progressed);assert!(step.released_allocation_bytes<=4096);}assert!(owner.terminal_is_empty());assert_eq!(owner.allocated_bytes(),0);}
        let f:serde_json::Value=serde_json::from_str(include_str!("@ENTITY_ID_SOURCE_FIXTURE@")).unwrap();let expected:serde_json::Value=serde_json::from_str(include_str!("@ENTITY_ID_SOURCE_EXPECTED@")).unwrap();assert_eq!(f["sourceBytes"],8194);assert_eq!(f["maximumBytes"],4096);assert_eq!(f["maximumItems"],1);assert_eq!(f["maximumAllocationBytes"],65536);
        let mut sources:PagedList<OwnedOperationBytes,2>=PagedList::empty();let mut allow=|_|true;let mut build=NativeEncodeControl::new(65536,&mut allow);
        for original in 0..2{let count=if original==0{8194}else{4};let mut source=OwnedOperationBytes::try_new(count,65536).unwrap();if original==0{source.write_bytes(f["wire"].as_str().unwrap().as_bytes(),&mut build).unwrap();for _ in 0..8192{source.write_bytes(&[32],&mut build).unwrap();}}else{for byte in f["secondSource"].as_array().unwrap(){source.write_bytes(&[byte.as_u64().unwrap()as u8],&mut build).unwrap();}}while !sources.has_reserved_slot(){let required=sources.next_allocation_bytes().unwrap();build.charge(required).unwrap();let step=sources.reserve_one(4096).unwrap();assert_eq!(step.allocated_bytes,required);}sources.push_reserved(source).ok().unwrap();}
        let first=sources.source_at(0).unwrap().get(0).unwrap()as*const u8;let allocated=sources.allocated_bytes()+sources.iter().map(OwnedOperationBytes::allocated_bytes).sum::<usize>();let parent=f["parent"].as_str().unwrap();let slot=f["slot"].as_str().unwrap();let options=Default::default();
        let render=|id:ids::EntityId,maximum:usize,control:&mut NativeEncodeControl<'_>|{let mut text:PagedText<65536>=PagedText::empty();let mut inline=InlineTextBuffer::empty();let mut long=false;let result=text.encode_with_inline(&mut inline,&mut long,maximum,control,|output|id.encode_into(output));assert!(!long);assert_eq!(text.allocated_bytes(),0);if result.is_ok(){let bytes=inline.borrow().unwrap().as_bytes();assert!(bytes.len()==22||bytes.len()==27);let length=bytes.len();let mut actual=[0;27];actual[..length].copy_from_slice(bytes);assert!(inline.close_one(1));assert!(inline.terminal_is_empty());assert!(text.terminal_is_empty());Ok((actual,length))}else{assert!(inline.borrow().is_err());if !inline.terminal_is_empty(){assert!(inline.close_one(1));}assert!(inline.terminal_is_empty());assert!(text.terminal_is_empty());Err(result.unwrap_err())}};
        for row in expected["children"].as_array().unwrap(){let order:Vec<usize>=row["order"].as_array().unwrap().iter().map(|index|index.as_u64().unwrap()as usize).collect();let operations=Order{sources:&sources,order:&order,missing:false};let mut control=NativeEncodeControl::new(65536,&mut allow);let id=ids::child_entity_id_from_source(&parent,&slot,&operations,7,&options,&mut control).unwrap();let(actual,length)=render(id,22,&mut control).unwrap();assert_eq!(&actual[..length],row["id"].as_str().unwrap().as_bytes());assert_eq!(control.owned_bytes(),0);let id=ids::child_entity_id_from_source(&parent,&slot,&operations,7,&options,&mut control).unwrap();assert!(render(id,21,&mut control).is_err());}
        let base:[[usize;2];4]=[[0,0],[1,1],[1,0],[0,1]];let lengths=[1,1,2,2];let identifiers=std::array::from_fn(|index|f["invocationChildren"][index]["id"].as_str().unwrap());let parent_order=[0,1];let parent_operations=Order{sources:&sources,order:&parent_order,missing:false};
        for row in expected["invocations"].as_array().unwrap(){let order:Vec<usize>=row["order"].as_array().unwrap().iter().map(|index|index.as_u64().unwrap()as usize).collect();let children=Children{identifiers,operations:std::array::from_fn(|index|Order{sources:&sources,order:&base[index][..lengths[index]],missing:false}),order:&order,missing:false};let mut indices:PagedList<usize,65536>=PagedList::empty();let mut control=NativeEncodeControl::new(65536,&mut allow);let id=ids::invocation_entity_id_from_source(&parent,&parent_operations,&children,&mut indices,&options,&mut control).unwrap();let(actual,length)=render(id,27,&mut control).unwrap();assert_eq!(&actual[..length],row["id"].as_str().unwrap().as_bytes());let original=row["sorted"].as_array().unwrap();assert_eq!(indices.len(),original.len());for(index,expected)in indices.iter().zip(original){assert_eq!(order[*index],expected.as_u64().unwrap()as usize);}assert_eq!(control.owned_bytes(),indices.allocated_bytes());let before=indices.allocated_bytes();assert!(ids::invocation_entity_id_from_source(&parent,&parent_operations,&children,&mut indices,&options,&mut control).is_err());assert_eq!(indices.allocated_bytes(),before);close_indices(&mut indices);}
        for mode in 0..5{let order=[0,1,2,3];let children=Children{identifiers,operations:std::array::from_fn(|index|Order{sources:&sources,order:&base[index][..lengths[index]],missing:false}),order:&order,missing:mode==4};let mut indices:PagedList<usize,65536>=PagedList::empty();let mut callback=|progress:semio_framework_value::native_encoding::NativeEncodeProgress|match mode{1=>progress.owned_bytes==0,2=>progress.completed<=4,3=>progress.completed<256,_=>true};let mut control=NativeEncodeControl::new(if mode==0{4095}else{65536},&mut callback);assert!(ids::invocation_entity_id_from_source(&parent,&parent_operations,&children,&mut indices,&options,&mut control).is_err());if mode==0{assert_eq!(indices.len(),0);assert_eq!(indices.allocated_bytes(),0);assert_eq!(control.owned_bytes(),0);}else{assert!(indices.allocated_bytes()>0);assert_eq!(control.owned_bytes(),indices.allocated_bytes());}close_indices(&mut indices);}
        let missing=Order{sources:&sources,order:&parent_order,missing:true};let mut control=NativeEncodeControl::new(65536,&mut allow);assert!(ids::child_entity_id_from_source(&parent,&slot,&missing,7,&options,&mut control).is_err());assert_eq!(control.owned_bytes(),0);assert_eq!(sources.source_at(0).unwrap().get(0).unwrap()as*const u8,first);assert_eq!(sources.source_at(0).unwrap().len(),8194);assert_eq!(sources.allocated_bytes()+sources.iter().map(OwnedOperationBytes::allocated_bytes).sum::<usize>(),allocated);
        for source in sources.iter_mut(){for _ in 0..8194+128{if source.close_one(1,4096).unwrap()==OperationByteCloseStep::Complete{break;}}assert!(source.terminal_is_empty());assert_eq!(source.allocated_bytes(),0);}while sources.pop().is_some(){}for _ in 0..128{if sources.terminal_is_empty(){break}let step=sources.release_empty_page(4096).unwrap();assert!(step.progressed);assert!(step.released_allocation_bytes<=4096);}assert!(sources.terminal_is_empty());assert_eq!(sources.allocated_bytes(),0);println!("[DEBUG] actual borrowed entity domains preserve full8194/source pointers; real paged scalar index stable sorting, initial4096, partial/sort/hash/missing refusals, actual short inline output extent and1/4096 physical disposal; no parent/Store/all-caller credit");
    }
